        n = len(s)
        half = n // 2
        if n % 2 == 0:
            left = s[:half]
            right = s[half:]
            pal = left + left[::-1]
        else:
            left = s[:half]
            mid = s[half]
            right = s[half+1:]
            pal = left + mid + left[::-1]
        return pal

    def increment_middle(s: str) -> str:
        n = len(s)
        s_list = list(s)
        mid = n // 2
        left_end = mid - 1
        right_start = mid + 1 if n % 2 else mid

        # Increment the middle digit(s)
        if n % 2 == 1:
            # Increment the middle digit
            if s_list[mid] != '9':
                s_list[mid] = str(int(s_list[mid]) + 1)
                # mirror left to right
                for i in range(left_end, -1, -1):
                    s_list[n - 1 - i] = s_list[i]
                return "".join(s_list)
            else:
                s_list[mid] = '0'
                # carry to left side
                i = left_end
                while i >= 0 and s_list[i] == '9':
                    s_list[i] = '0'
                    s_list[n - 1 - i] = '0'
                    i -= 1
                if i < 0:
                    # all 9's in left + mid handled outside
                    return None
                s_list[i] = str(int(s_list[i]) + 1)
                s_list[n - 1 - i] = s_list[i]
                # mirror the rest
                for j in range(i-1, -1, -1):
                    s_list[n - 1 - j] = s_list[j]
                return "".join(s_list)
        else:
            # even length: increment left side and mirror
            i = left_end
            while i >= 0 and s_list[i] == '9':
                s_list[i] = '0'
                s_list[n - 1 - i] = '0'
                i -= 1
            if i < 0:
                return None
            s_list[i] = str(int(s_list[i]) + 1)
            s_list[n - 1 - i] = s_list[i]
            # mirror the rest
            for j in range(i-1, -1, -1):
                s_list[n - 1 - j] = s_list[j]
            return "".join(s_list)

    pal = make_palindrome(s)
    if int(pal) > num:
        return int(pal)
    else:
        incremented = increment_middle(pal)
        if incremented is not None:
