def get_total_number_of_sequences(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        return 0
    if n == 1:
        return m

    # dp[i][x] = number of sequences of length i starting with element x
    # We want sum over x=1..m of dp[n][x]

    # Actually, it's easier to think forward:
    # For length 1, dp[1][x] = 1 for all x in [1..m]
    # For length i > 1, dp[i][x] = sum of dp[i-1][y] over all y where x >= 2*y

    # We'll implement this bottom-up with memoization.

    from collections import defaultdict

    # Initialize dp for length 1
    dp_prev = [1] * (m + 1)  # 1-based indexing; dp_prev[x] = count sequences length 1 starting at x

    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # For each possible current element x, find all previous elements y satisfying x >= 2*y
        # => y <= x//2
        # dp_curr[x] = sum of dp_prev[y] for y in [1 .. x//2]
        prefix_sum = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp_prev[i]

        for x in range(1, m + 1):
            limit = x // 2
            if limit >= 1:
                dp_curr[x] = prefix_sum[limit]
            else:
                dp_curr[x] = 0

        dp_prev = dp_curr

    return sum(dp_prev[1:])

