    half_len = (length + 1) // 2  # middle included if odd length

    left_half = s[:half_len]
    # Construct palindrome candidate by mirroring left half
    palindrome = make_palindrome(left_half, odd_length)
    palindrome_num = int(palindrome)

    if palindrome_num > n:
        return palindrome_num
    else:
        # Need to increment the left half and then mirror again
        incremented_left = increment_str_num(left_half)
        # Handle overflow: if length changes after incrementing left half
        if len(incremented_left) > len(left_half):
            # Example: 999 -> incremented left half '1000' means palindrome length increases by 1
            # For this case, palindrome is '1' + '0'*(length-1) + '1'
            return int('1' + ('0' * (length - 1)) + '1')
        else:
            palindrome = make_palindrome(incremented_left, odd_length)
