def find_solution(a, b, n):
    # Handle trivial cases
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        return None
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    # We want to find non-negative integers x,y >= 0 such that a*x + b*y = n
    # Iterate over possible x to find y:
    # y = (n - a*x)/b must be integer and >= 0
    # To reduce search space, we limit x to [0, max_x] where max_x chosen heuristically

    # If a or b is negative, the range for x is not straightforward.
    # We can try x in 0..(n//a) if a>0, or 0..some limit if a<0, but better to
    # try a reasonable range by checking from 0 to a large enough bound.

    # Let's try a brute force approach with a reasonable bound:
    # max_x can be from 0 up to max(0, n//a) if a>0 else up to some positive bound.
    # Similarly, if a < 0, increasing x makes a*x more negative, so max_x could be 0.
    # Since x,y >=0, we can only try values that don't make a*x exceed n if a>0.

    # To cover negative a or b, let's try from 0 to some large limit (like max(abs(n), abs(a), abs(b)) + 1)
    # but that might be inefficient. Instead, we can bound x by:
    # if a>0: max_x = n//a if n>=0 else 0
    # if a<0: since x>=0 and a*x <= 0, a*x + b*y = n implies b*y = n - a*x, so n - a*x >=0 for y >=0.
    # So for a<0, x can be up to something that keeps n - a*x >=0.

    # To be safe and efficient, we compute bounds accordingly:

    def valid_y(x):
        numerator = n - a * x
        if b == 0:
            return numerator == 0
        if numerator % b != 0:
            return False
        y = numerator // b
        return y >= 0

    # Determine bounds for x:
    # Lower bound is 0
    lower_x = 0
    # Upper bound:
    # For a > 0 and n >=0, max_x = n // a
    # For a < 0, since x >=0 and n - a*x >= 0 => x <= n / (-a) if n>=0 else 0
    # For negative n, it's tricky, but since x,y >= 0, no solution if n negative and both a,b positive.
    # We'll just pick an upper bound conservatively:
    max_abs = max(abs(n), abs(a), abs(b))

    if a > 0:
        max_x = n // a if n >= 0 else 0
    elif a < 0:
        max_x = n // a if a != 0 and n // a >= 0 else max_abs
        # n // a is negative or zero, but x >= 0, so max_x cannot be negative
        max_x = max(0, max_x)
    else:
        max_x = max_abs

    max_x = max(max_x, 0)

    # Iterate over x in [0, max_x]
    for x in range(lower_x, max_x + 1):
        numerator = n - a*x
        if b == 0:
            if numerator == 0:
                # y can be any integer, but must be >= 0
                return (x, 0)
            continue
        if numerator % b == 0:
            y = numerator // b
            if y >= 0:
                return (x, y)
    return None

