        elif isinstance(v, (list, tuple)):
            # Check max depth inside any dict inside list/tuple
            max_subdepth = 0
            for item in v:
                if isinstance(item, dict):
                    max_subdepth = max(max_subdepth, dict_depth(item))
                elif isinstance(item, (list, tuple)):
                    # Recursively check inside nested list/tuple
                    # Wrap the item in a dummy dict to reuse logic:
                    # but since we only count dicts for depth,
                    # we just check each element similarly.
                    # So we can make a helper function or inline.

                    # To avoid code duplication, we use a helper function here:
                    def check_nested(obj):
                        if isinstance(obj, dict):
                            return dict_depth(obj)
                        elif isinstance(obj, (list, tuple)):
                            return max((check_nested(x) for x in obj), default=0)
                        else:
