def find_solution(a, b, n):
    # Handle trivial case n == 0
    if n == 0:
        return (0, 0)

    # If both a and b are zero, no solution unless n == 0 (already handled)
    if a == 0 and b == 0:
        return 'No solution'

    # If a == 0, then we must have b*y = n
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return 'No solution'

    # If b == 0, then we must have a*x = n
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return 'No solution'

    # General case:
    # Try x from 0 up to max possible where a*x <= n (or down if a negative)
    # Since x,y must be >= 0, we only consider x>=0 and y>=0.

    # To avoid infinite loops with negative a or b, 
    # we consider the sign and only iterate where the value is feasible.

    # Define range for x:
    # Because x >= 0 and a*x <= n (if a>0), else if a<0, a*x <= n means x <= n/a (negative)
    # But since x>=0, if a<0 and n>=0, no x>=0 satisfies a*x=n or less necessarily.
    # So we only consider a>0 or a<0 separately.

    # Let's find valid x values in range.
    # Since x,y >=0, and a*x + b*y = n, y = (n - a*x)/b must be >= 0 and integer.

    # To handle sign of a and b:
    # We'll iterate x from 0 up to some max_x (depending on sign and n)
    # and check if y is integer and >=0.

    # Find max_x to check:
    # If a > 0: max_x = n // a if n>=0 else no x>=0 satisfies
    # If a < 0: since x>=0, a*x <= 0, if n>=0, a*x <= 0 < n, so no solution
    # If n < 0 and a < 0: max_x = n // a (n and a negative, so max_x positive)
    # But since y >= 0, we must check accordingly.

    # So let's just brute force x from 0 to some upper bound.

    # Let's define max_x:
    if a > 0:
        max_x = n // a if n >= 0 else -1
    elif a < 0:
        # If a < 0, and n >= 0, no solution since a*x <= 0 < n
        # If n < 0, max_x = n // a (integer division), but x >= 0, so max_x must be >=0 to iterate
        if n >= 0:
            return 'No solution'
        else:
            max_x = n // a  # both negative, so max_x positive or zero
            if max_x < 0:
                return 'No solution'
    else:
        # a == 0 handled above
        return 'No solution'

    # Because a and b can be negative, we must verify y >= 0 and integer.
    for x in range(max_x + 1):
        remainder = n - a * x
        if b == 0:
            # Already handled above, but just in case
            continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return 'No solution'

