def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 1:
        return m  # any number from 1 to m

    # dp[i][x] = number of sequences of length i starting with element x
    # We'll compute from the last element backwards using memoization

    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(i: int, prev: int) -> int:
        # i: current position in sequence (1-based)
        # prev: previous element chosen

        if i == n:
            # Last element chosen, sequence complete
            return 1

        total = 0
        start = 2 * prev  # next element must be >= 2 * prev
        for next_val in range(start, m + 1):
            total += count_sequences(i + 1, next_val)
        return total

    total_sequences = 0
    for start_val in range(1, m + 1):
        total_sequences += count_sequences(1, start_val)

    return total_sequences

