def find_Max(nums, low, high):
    # Base case: if the subarray has only one element
    if low == high:
        return nums[low]

    # If the array segment is already sorted, the max is at high
    if nums[low] < nums[high]:
        return nums[high]

    mid = (low + high) // 2

    # Check if mid element is greater than its next element
    if mid < high and nums[mid] > nums[mid + 1]:
        return nums[mid]

    # Check if mid element is smaller than its previous element
    if mid > low and nums[mid] < nums[mid - 1]:
        return nums[mid - 1]

    # Decide which half to choose for next step
    if nums[mid] > nums[low]:
        # Left part is sorted, max must be in right part
        return find_Max(nums, mid + 1, high)
    else:
        # Right part is sorted, max must be in left part
        return find_Max(nums, low, mid - 1)

