        total = 0
        start = prev * 2
        # next element must be >= 2 * prev and <= m
        for nxt in range(start, m + 1):
            total += count_sequences(length + 1, nxt)
        return total

    # For sequences of length 1, we can start with any element from 1 to m
    total_sequences = 0
    for start in range(1, m + 1):
        total_sequences += count_sequences(1, start)

    return total_sequences

import re

def text_match_two_three(text):
    return bool(re.fullmatch(r'ab{2,3}', text))

def flatten_list(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten_list(item))
        else:
            result.append(item)
    return result

def dict_depth(d):
    if not isinstance(d, dict) or not d:
        return 1
    else:
        return 1 + max(dict_depth(v) for v in d.values() if isinstance(v, dict))

def remove_column(nested_list, col_idx):
    result = []
    for row in nested_list:
        if col_idx < len(row):
            # Create a new row without the element at col_idx
            new_row = row[:col_idx] + row[col_idx+1:]
            result.append(new_row)
        else:
            # Row unchanged if col_idx out of range
            result.append(row[:])
    return result

def min_flip_to_make_string_alternate(s: str) -> int:
    if not s:
        return 0

    # Pattern 1: starting with '0'
    flips_start_0 = 0
    # Pattern 2: starting with '1'
    flips_start_1 = 0

    for i, ch in enumerate(s):
        expected_char_0 = '0' if i % 2 == 0 else '1'
        expected_char_1 = '1' if i % 2 == 0 else '0'

        if ch != expected_char_0:
            flips_start_0 += 1
        if ch != expected_char_1:
            flips_start_1 += 1

    return min(flips_start_0, flips_start_1)

def smallest_missing(arr, start, end):
    # Base case: if start > end, the smallest missing is start
    if start > end:
        return start

    mid = (start + end) // 2

    # If the element at mid is equal to mid (assuming arr is sorted and ideally starts at 0),
    # then the missing element must be in the right half
    if arr[mid] == mid:
        return smallest_missing(arr, mid + 1, end)
    else:
        # Missing element is in the left half (including mid)
        return smallest_missing(arr, start, mid - 1)

def permute_string(s):
    def backtrack(path, used):
        if len(path) == len(s):
            print("".join(path))
            return
        for i in range(len(s)):
            if not used[i]:
                used[i] = True
                path.append(s[i])
                backtrack(path, used)
                path.pop()
                used[i] = False

    used = [False] * len(s)
    backtrack([], used)

def multi_list(rows, cols):
    if rows == 0:
        return []
    return [[None] * cols for _ in range(rows)]

def highest_Power_of_2(n: int) -> int:
    if n < 1:
        return 0
    power = 1
    while power <= n:
        power <<= 1
    return power >> 1

def check_greater(num, arr):
    if not arr:
        raise ValueError("Array is empty; cannot compare with elements.")
    return all(num > x for x in arr)

def find_remainder(arr, n):
    if n == 0:
        raise ValueError("Divisor n must be non-zero")
    product = 1
    for num in arr:
        product = (product * (num % n)) % n
    return product

def find_Max(arr, low, high):
    # If the subarray is not rotated (sorted ascending), max is at high
    if arr[low] <= arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2

        # Check if mid is pivot (max element)
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to search
        if arr[mid] >= arr[low]:
            # Left half is sorted, max must be in right half
            low = mid + 1
        else:
            # Right half is sorted, max must be in left half
            high = mid - 1

    # Fallback (should not reach here if input is rotated sorted array)
    return arr[low]

def sum_digits(n: int) -> int:
    if n < 0:
        raise ValueError("Negative input is invalid")
    return sum(int(d) for d in str(n))

from math import comb

def sum_Of_product(n):
    return sum(comb(n, k) * comb(n, k) for k in range(n+1))

def move_num(s):
    chars = [c for c in s if not c.isdigit()]
    digits = [c for c in s if c.isdigit()]
    return ''.join(chars + digits)

from collections import Counter

def check_subset(t1, t2):
    c1 = Counter(t1)
    c2 = Counter(t2)
    for elem, count in c1.items():
        if c2[elem] < count:
            return False
    return True

def recur_gcd(a: int, b: int) -> int:
    if a == 0 and b == 0:
        raise ValueError("gcd(0, 0) is undefined")
    a, b = abs(a), abs(b)
    if b == 0:
        return a
    return recur_gcd(b, a % b)

import re

def text_match(text: str) -> bool:
    return bool(re.fullmatch(r'a[b]*', text))

def filter_data(students):
    filtered = {}
    for student, data in students.items():
        filtered[student] = {}
        if 'height' in data:
            filtered[student]['height'] = data['height']
        if 'width' in data:
            filtered[student]['width'] = data['width']
    return filtered

import re

def capital_words_spaces(s: str) -> str:
    # Insert a space before each capital letter that is preceded by any letter
    return re.sub(r'(?<=[a-zA-Z])([A-Z])', r' \1', s)

def sum_column(matrix, col_idx):
    total = 0
    for row in matrix:
        if len(row) > col_idx:
            total += row[col_idx]
    return total

def is_triangleexists(a, b, c):
    tol = 1e-9
    if a <= 0 or b <= 0 or c <= 0:
        return False
    total = a + b + c
    return abs(total - 180) <= tol

def length_Of_Last_Word(s: str) -> int:
    s = s.rstrip()  # Remove trailing spaces
    if not s:
        return 0
    return len(s.split(' ')[-1])

def lcm(a: int, b: int) -> int:
    from math import gcd
    return a * b // gcd(a, b)

def div_of_nums(numbers, m, n):
    if m == 0 or n == 0:
        raise ValueError("m and n must be non-zero to avoid division by zero.")
    return list(filter(lambda x: x % m == 0 and x % n == 0, numbers))

def substract_elements(t1, t2):
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        return tuple(substract_elements(a, b) for a, b in zip(t1, t2))
    else:
        return t1 - t2

def tuple_to_set(t):
    if not isinstance(t, tuple):
        raise TypeError("Expected a single tuple argument")
    return set(t)

def get_noOfways(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = 1
    dp[2] = 2  # Two ways: two vertical or two horizontal dominoes
    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]
